SET NAMES utf8mb4;
SET time_zone = '+02:00';
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `ohrid_summer` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `ohrid_summer`;

DROP TABLE IF EXISTS page_views, cookie_preferences, contact_messages, newsletter_subscribers,
  faq_translations, faqs, team_member_translations, team_members, partner_translations, partners,
  sponsor_translations, sponsors, gallery_image_translations, gallery_images,
  gallery_album_translations, gallery_albums, news_translations, news, news_category_translations,
  news_categories, favorites, reservations, tickets, order_items, orders, ticket_type_translations,
  ticket_types, event_seat_blocks, event_artists, event_translations, events, artist_translations,
  artists, venue_seats, venue_translations, venues, edition_translations, festival_editions,
  category_translations, categories, login_attempts, users, roles;

SET FOREIGN_KEY_CHECKS = 1;

DROP TABLE IF EXISTS app_meta;
CREATE TABLE app_meta (k VARCHAR(40) NOT NULL PRIMARY KEY, v VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- users
CREATE TABLE roles (
  id TINYINT UNSIGNED PRIMARY KEY,
  code VARCHAR(20) NOT NULL UNIQUE,
  name VARCHAR(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE users (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  role_id TINYINT UNSIGNED NOT NULL DEFAULT 2,
  first_name VARCHAR(80) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  email VARCHAR(190) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  phone VARCHAR(40) NULL,
  preferred_lang CHAR(2) NOT NULL DEFAULT 'mk',
  newsletter TINYINT(1) NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login_at DATETIME NULL,
  CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE login_attempts (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(190) NOT NULL,
  ip_hash CHAR(64) NOT NULL,
  attempted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_attempts (email, attempted_at),
  INDEX idx_attempts_ip (ip_hash, attempted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- taxonomy
CREATE TABLE categories (
  id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(40) NOT NULL UNIQUE,
  icon VARCHAR(30) NOT NULL DEFAULT 'spark',
  color CHAR(7) NOT NULL DEFAULT '#134a66',
  sort_order SMALLINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE category_translations (
  category_id TINYINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  name VARCHAR(80) NOT NULL,
  PRIMARY KEY (category_id, lang),
  CONSTRAINT fk_cat_tr FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE festival_editions (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  year SMALLINT UNSIGNED NOT NULL UNIQUE,
  edition_number SMALLINT UNSIGNED NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  visitors INT UNSIGNED NOT NULL DEFAULT 0,
  countries SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  CONSTRAINT chk_edition_dates CHECK (end_date >= start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE edition_translations (
  edition_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  theme VARCHAR(120) NOT NULL,
  summary TEXT NULL,
  PRIMARY KEY (edition_id, lang),
  CONSTRAINT fk_ed_tr FOREIGN KEY (edition_id) REFERENCES festival_editions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- venues & seats
CREATE TABLE venues (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(80) NOT NULL UNIQUE,
  image VARCHAR(255) NULL,
  layout_type ENUM('amphitheatre','nave','courtyard','terrace','hall','open') NOT NULL DEFAULT 'hall',
  seating_type ENUM('seated','general') NOT NULL DEFAULT 'seated',
  capacity INT UNSIGNED NOT NULL DEFAULT 0,
  latitude DECIMAL(9,6) NULL,
  longitude DECIMAL(9,6) NULL,
  map_x DECIMAL(5,2) NOT NULL DEFAULT 50,
  map_y DECIMAL(5,2) NOT NULL DEFAULT 50,
  address VARCHAR(255) NOT NULL DEFAULT '',
  address_en VARCHAR(255) NOT NULL DEFAULT '',
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  sort_order SMALLINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE venue_translations (
  venue_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  name VARCHAR(160) NOT NULL,
  short_description VARCHAR(400) NULL,
  description TEXT NULL,
  accessibility TEXT NULL,
  seating_info TEXT NULL,
  PRIMARY KEY (venue_id, lang),
  CONSTRAINT fk_venue_tr FOREIGN KEY (venue_id) REFERENCES venues(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE venue_seats (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  venue_id SMALLINT UNSIGNED NOT NULL,
  section VARCHAR(10) NOT NULL,
  row_label VARCHAR(10) NOT NULL,
  seat_number SMALLINT UNSIGNED NOT NULL,
  seat_type ENUM('standard','vip','accessible') NOT NULL DEFAULT 'standard',
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  pos_x SMALLINT NOT NULL,
  pos_y SMALLINT NOT NULL,
  UNIQUE KEY uq_seat (venue_id, section, row_label, seat_number),
  CONSTRAINT fk_seat_venue FOREIGN KEY (venue_id) REFERENCES venues(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- artists
CREATE TABLE artists (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(120) NOT NULL UNIQUE,
  image VARCHAR(255) NULL,
  category_id TINYINT UNSIGNED NOT NULL,
  country_code CHAR(2) NOT NULL DEFAULT 'MK',
  is_ensemble TINYINT(1) NOT NULL DEFAULT 0,
  website VARCHAR(255) NULL,
  instagram VARCHAR(80) NULL,
  facebook VARCHAR(80) NULL,
  youtube VARCHAR(80) NULL,
  is_featured TINYINT(1) NOT NULL DEFAULT 0,
  is_published TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_artist_cat FOREIGN KEY (category_id) REFERENCES categories(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE artist_translations (
  artist_id INT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  name VARCHAR(160) NOT NULL,
  role VARCHAR(120) NULL,
  biography TEXT NULL,
  PRIMARY KEY (artist_id, lang),
  CONSTRAINT fk_artist_tr FOREIGN KEY (artist_id) REFERENCES artists(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- events
CREATE TABLE events (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(140) NOT NULL UNIQUE,
  edition_id SMALLINT UNSIGNED NULL,
  category_id TINYINT UNSIGNED NOT NULL,
  venue_id SMALLINT UNSIGNED NOT NULL,
  starts_at DATETIME NOT NULL,
  duration_min SMALLINT UNSIGNED NOT NULL DEFAULT 90,
  image VARCHAR(255) NULL,
  price_standard DECIMAL(10,2) NOT NULL DEFAULT 0,
  price_vip DECIMAL(10,2) NULL,
  seating_mode ENUM('seated','general') NULL COMMENT 'NULL = use the venue default',
  capacity INT UNSIGNED NULL COMMENT 'general admission capacity',
  country VARCHAR(160) NULL,
  is_featured TINYINT(1) NOT NULL DEFAULT 0,
  status ENUM('published','draft','cancelled') NOT NULL DEFAULT 'published',
  sales_status ENUM('open','closed') NOT NULL DEFAULT 'open',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_events_start (status, starts_at),
  INDEX idx_events_cat (category_id),
  INDEX idx_events_venue (venue_id),
  CONSTRAINT chk_event_price CHECK (price_standard >= 0),
  CONSTRAINT fk_event_edition FOREIGN KEY (edition_id) REFERENCES festival_editions(id) ON DELETE SET NULL,
  CONSTRAINT fk_event_cat FOREIGN KEY (category_id) REFERENCES categories(id),
  CONSTRAINT fk_event_venue FOREIGN KEY (venue_id) REFERENCES venues(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_translations (
  event_id INT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  title VARCHAR(200) NOT NULL,
  subtitle VARCHAR(255) NULL,
  description TEXT NULL,
  programme TEXT NULL,
  director VARCHAR(160) NULL,
  PRIMARY KEY (event_id, lang),
  FULLTEXT KEY ft_event (title, subtitle, description),
  CONSTRAINT fk_event_tr FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_artists (
  event_id INT UNSIGNED NOT NULL,
  artist_id INT UNSIGNED NOT NULL,
  role ENUM('performer','soloist','conductor','director','host') NOT NULL DEFAULT 'performer',
  sort_order SMALLINT NOT NULL DEFAULT 0,
  PRIMARY KEY (event_id, artist_id),
  CONSTRAINT fk_ea_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
  CONSTRAINT fk_ea_artist FOREIGN KEY (artist_id) REFERENCES artists(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE event_seat_blocks (
  event_id INT UNSIGNED NOT NULL,
  seat_id INT UNSIGNED NOT NULL,
  reason VARCHAR(120) NULL,
  PRIMARY KEY (event_id, seat_id),
  CONSTRAINT fk_block_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
  CONSTRAINT fk_block_seat FOREIGN KEY (seat_id) REFERENCES venue_seats(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- ticketing
CREATE TABLE ticket_types (
  id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(20) NOT NULL UNIQUE,
  discount_percent TINYINT UNSIGNED NOT NULL DEFAULT 0,
  sort_order SMALLINT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  CONSTRAINT chk_discount CHECK (discount_percent <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ticket_type_translations (
  ticket_type_id TINYINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  name VARCHAR(80) NOT NULL,
  description VARCHAR(255) NULL,
  PRIMARY KEY (ticket_type_id, lang),
  CONSTRAINT fk_tt_tr FOREIGN KEY (ticket_type_id) REFERENCES ticket_types(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE orders (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  order_number VARCHAR(20) NOT NULL UNIQUE,
  user_id INT UNSIGNED NULL,
  event_id INT UNSIGNED NOT NULL,
  customer_name VARCHAR(160) NOT NULL,
  customer_email VARCHAR(190) NOT NULL,
  status ENUM('pending','reserved','paid','cancelled','failed','refunded') NOT NULL DEFAULT 'pending',
  payment_method ENUM('visa','mastercard','maestro','bank_transfer','box_office') NOT NULL,
  payment_status ENUM('unpaid','paid','failed','refunded') NOT NULL DEFAULT 'unpaid',
  card_brand VARCHAR(20) NULL,
  card_last4 CHAR(4) NULL,
  subtotal DECIMAL(10,2) NOT NULL DEFAULT 0,
  service_fee DECIMAL(10,2) NOT NULL DEFAULT 0,
  total DECIMAL(10,2) NOT NULL DEFAULT 0,
  currency CHAR(3) NOT NULL DEFAULT 'MKD',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  paid_at DATETIME NULL,
  expires_at DATETIME NULL,
  INDEX idx_orders_user (user_id, created_at),
  INDEX idx_orders_status (status),
  CONSTRAINT fk_order_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_order_event FOREIGN KEY (event_id) REFERENCES events(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE order_items (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  order_id INT UNSIGNED NOT NULL,
  ticket_type_id TINYINT UNSIGNED NOT NULL,
  seat_id INT UNSIGNED NULL,
  zone ENUM('standard','vip') NOT NULL DEFAULT 'standard',
  unit_price DECIMAL(10,2) NOT NULL,
  CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
  CONSTRAINT fk_oi_type FOREIGN KEY (ticket_type_id) REFERENCES ticket_types(id),
  CONSTRAINT fk_oi_seat FOREIGN KEY (seat_id) REFERENCES venue_seats(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE tickets (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  order_id INT UNSIGNED NOT NULL,
  order_item_id INT UNSIGNED NOT NULL UNIQUE,
  event_id INT UNSIGNED NOT NULL,
  seat_id INT UNSIGNED NULL,
  ticket_code VARCHAR(24) NOT NULL UNIQUE,
  status ENUM('valid','reserved','used','cancelled') NOT NULL DEFAULT 'valid',
  -- a seat can be held by only one non-cancelled ticket per event (prevents double selling)
  active_seat_id INT UNSIGNED AS (IF(status = 'cancelled', NULL, seat_id)) STORED,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_event_active_seat (event_id, active_seat_id),
  INDEX idx_tickets_event (event_id, status),
  CONSTRAINT fk_ticket_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
  CONSTRAINT fk_ticket_item FOREIGN KEY (order_item_id) REFERENCES order_items(id) ON DELETE CASCADE,
  CONSTRAINT fk_ticket_event FOREIGN KEY (event_id) REFERENCES events(id),
  CONSTRAINT fk_ticket_seat FOREIGN KEY (seat_id) REFERENCES venue_seats(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- temporary seat holds during checkout (15 minutes)
CREATE TABLE reservations (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NOT NULL,
  event_id INT UNSIGNED NOT NULL,
  seat_id INT UNSIGNED NOT NULL,
  expires_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_hold (event_id, seat_id),
  INDEX idx_hold_exp (expires_at),
  CONSTRAINT fk_hold_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_hold_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
  CONSTRAINT fk_hold_seat FOREIGN KEY (seat_id) REFERENCES venue_seats(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE favorites (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NOT NULL,
  entity_type ENUM('event','artist') NOT NULL,
  entity_id INT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_fav (user_id, entity_type, entity_id),
  CONSTRAINT fk_fav_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- news
CREATE TABLE news_categories (
  id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(40) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE news_category_translations (
  category_id TINYINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  name VARCHAR(80) NOT NULL,
  PRIMARY KEY (category_id, lang),
  CONSTRAINT fk_ncat_tr FOREIGN KEY (category_id) REFERENCES news_categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE news (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(140) NOT NULL UNIQUE,
  category_id TINYINT UNSIGNED NOT NULL,
  related_event_id INT UNSIGNED NULL,
  author_name VARCHAR(120) NOT NULL,
  image VARCHAR(255) NULL,
  is_featured TINYINT(1) NOT NULL DEFAULT 0,
  status ENUM('published','draft') NOT NULL DEFAULT 'published',
  published_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_news_pub (status, published_at),
  CONSTRAINT fk_news_cat FOREIGN KEY (category_id) REFERENCES news_categories(id),
  CONSTRAINT fk_news_event FOREIGN KEY (related_event_id) REFERENCES events(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE news_translations (
  news_id INT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  title VARCHAR(220) NOT NULL,
  excerpt VARCHAR(500) NULL,
  body MEDIUMTEXT NULL,
  PRIMARY KEY (news_id, lang),
  CONSTRAINT fk_news_tr FOREIGN KEY (news_id) REFERENCES news(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- gallery
CREATE TABLE gallery_albums (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(120) NOT NULL UNIQUE,
  album_type ENUM('event','venue','festival','backstage') NOT NULL DEFAULT 'festival',
  edition_id SMALLINT UNSIGNED NULL,
  event_id INT UNSIGNED NULL,
  venue_id SMALLINT UNSIGNED NULL,
  cover_image VARCHAR(255) NULL,
  sort_order SMALLINT NOT NULL DEFAULT 0,
  is_published TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_album_ed FOREIGN KEY (edition_id) REFERENCES festival_editions(id) ON DELETE SET NULL,
  CONSTRAINT fk_album_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL,
  CONSTRAINT fk_album_venue FOREIGN KEY (venue_id) REFERENCES venues(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE gallery_album_translations (
  album_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  title VARCHAR(160) NOT NULL,
  description VARCHAR(500) NULL,
  PRIMARY KEY (album_id, lang),
  CONSTRAINT fk_album_tr FOREIGN KEY (album_id) REFERENCES gallery_albums(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE gallery_images (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  album_id SMALLINT UNSIGNED NOT NULL,
  image VARCHAR(255) NOT NULL,
  sort_order SMALLINT NOT NULL DEFAULT 0,
  CONSTRAINT fk_img_album FOREIGN KEY (album_id) REFERENCES gallery_albums(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE gallery_image_translations (
  image_id INT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  caption VARCHAR(255) NOT NULL,
  PRIMARY KEY (image_id, lang),
  CONSTRAINT fk_img_tr FOREIGN KEY (image_id) REFERENCES gallery_images(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- organisation
CREATE TABLE sponsors (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  logo VARCHAR(255) NULL,
  website VARCHAR(255) NULL,
  level ENUM('general','gold','silver','media') NOT NULL DEFAULT 'silver',
  sort_order SMALLINT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sponsor_translations (
  sponsor_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  description VARCHAR(500) NULL,
  PRIMARY KEY (sponsor_id, lang),
  CONSTRAINT fk_sp_tr FOREIGN KEY (sponsor_id) REFERENCES sponsors(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE partners (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  logo VARCHAR(255) NULL,
  website VARCHAR(255) NULL,
  partner_type ENUM('institutional','network','cultural','hospitality','media') NOT NULL DEFAULT 'cultural',
  sort_order SMALLINT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE partner_translations (
  partner_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  description VARCHAR(500) NULL,
  PRIMARY KEY (partner_id, lang),
  CONSTRAINT fk_pt_tr FOREIGN KEY (partner_id) REFERENCES partners(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE team_members (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(80) NOT NULL UNIQUE,
  image VARCHAR(255) NULL,
  email VARCHAR(190) NULL,
  department ENUM('management','programme','production','communication','visitors','international') NOT NULL DEFAULT 'programme',
  sort_order SMALLINT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE team_member_translations (
  member_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  name VARCHAR(120) NOT NULL,
  position VARCHAR(160) NOT NULL,
  bio VARCHAR(600) NULL,
  PRIMARY KEY (member_id, lang),
  CONSTRAINT fk_team_tr FOREIGN KEY (member_id) REFERENCES team_members(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE faqs (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  topic ENUM('tickets','reservations','payment','venues','refunds','accessibility','programme','festival') NOT NULL,
  sort_order SMALLINT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE faq_translations (
  faq_id SMALLINT UNSIGNED NOT NULL,
  lang CHAR(2) NOT NULL,
  question VARCHAR(255) NOT NULL,
  answer TEXT NOT NULL,
  PRIMARY KEY (faq_id, lang),
  CONSTRAINT fk_faq_tr FOREIGN KEY (faq_id) REFERENCES faqs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------- engagement & privacy
CREATE TABLE newsletter_subscribers (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(190) NOT NULL UNIQUE,
  name VARCHAR(120) NULL,
  lang CHAR(2) NOT NULL DEFAULT 'mk',
  status ENUM('active','unsubscribed') NOT NULL DEFAULT 'active',
  consent_at DATETIME NOT NULL,
  token CHAR(32) NOT NULL,
  user_id INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_nl_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE contact_messages (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  email VARCHAR(190) NOT NULL,
  phone VARCHAR(40) NULL,
  topic ENUM('general','tickets','accessibility','press','volunteering','partnership') NOT NULL DEFAULT 'general',
  subject VARCHAR(200) NOT NULL,
  message TEXT NOT NULL,
  lang CHAR(2) NOT NULL DEFAULT 'mk',
  status ENUM('new','read','answered') NOT NULL DEFAULT 'new',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_msg_status (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE cookie_preferences (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  consent_id CHAR(32) NOT NULL UNIQUE,
  user_id INT UNSIGNED NULL,
  preferences TINYINT(1) NOT NULL DEFAULT 0,
  analytics TINYINT(1) NOT NULL DEFAULT 0,
  ip_hash CHAR(64) NULL,
  user_agent VARCHAR(255) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_cookie_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE page_views (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  path VARCHAR(255) NOT NULL,
  lang CHAR(2) NOT NULL,
  viewed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_views_time (viewed_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
--  DEMO DATA
-- =====================================================================

Од 2001 година театарот е главна сцена на Охридско лето: тука се одржуваат свеченото отворање, оперските и балетските продукции и големите оркестарски концерти. Акустиката на камените скалила е извонредна и за глас и за оркестар.','Пристапот за посетители во инвалидска количка е од горниот влез (ул. Илинденска), со резервирани места во првиот ред. Скалилата се камени и нерамни — препорачуваме удобни обувки. Перничиња за седење се изнајмуваат на влезот.','Нумерирани места на камените скалила, поделени во три сектори (лев, централен, десен). VIP-местата се во првите редови на централниот сектор.'),
(1,'en','Antique Theatre','The Hellenistic theatre in the heart of the Old Town — the festival''s main stage since 2001.','Ohrid''s Antique Theatre was built around 200 BC and is the only theatre from the Hellenistic period in North Macedonia. Set between the Upper Gate and Samuel''s Fortress, it looks out over the lake, which makes every evening here memorable.

Since 2001 the theatre has been the main stage of Ohrid Summer: the opening ceremony, opera and ballet productions and the large orchestral concerts all take place here. The acoustics of the stone tiers suit both voice and orchestra remarkably well.','Wheelchair access is through the upper entrance (Ilindenska St.), with reserved spaces in the first row. The stone tiers are uneven — comfortable shoes are recommended. Seat cushions can be rented at the entrance.','Numbered seats on the stone tiers, in three sections (left, centre, right). VIP seats are in the front rows of the centre section.'),
(2,'mk','Црква „Св. Софија“','Катедралната црква од XI век каде што на 4 август 1961 година се одржа првиот концерт на фестивалот.','Соборниот храм „Св. Софија“ е еден од најзначајните споменици на средновековната уметност во Европа, со фрески од XI век. Токму тука, на 4 август 1961 година, се одржа концертот со кој започна Охридско лето.

Денес црквата е домот на камерната музика, рециталите и хорската музика. Природната резонанца на просторот бара внимателно избран репертоар — и затоа концертите во „Св. Софија“ се меѓу најбараните во програмата.','Главниот влез има мала рампа. Внатре подот е рамен. Обезбедени се две места за инвалидски колички во последниот ред. Фотографирањето со блиц не е дозволено поради заштитата на фреските.','Нумерирани столчиња во наосот, поделени со централна патека. Некои места зад столбовите не се продаваат поради ограничена видливост.'),
(2,'en','Church of St. Sophia','The 11th-century cathedral where the festival''s very first concert took place on 4 August 1961.','The Cathedral of St. Sophia is one of the most important monuments of medieval art in Europe, with frescoes from the 11th century. It was here, on 4 August 1961, that the concert which began Ohrid Summer took place.

Today the church is the home of chamber music, recitals and choral music. The natural resonance of the space calls for carefully chosen repertoire — which is why concerts at St. Sophia are among the most sought-after in the programme.','The main entrance has a small ramp and the floor inside is level. Two wheelchair spaces are provided in the last row. Flash photography is not allowed in order to protect the frescoes.','Numbered chairs in the nave, divided by a central aisle. Some seats behind the pillars are not sold due to restricted view.'),
(3,'mk','Предворје на „Св. Софија“','Летна сцена на отворено пред катедралата, за солисти, поезија и вечери под ѕвездите.','Предворјето на „Св. Софија“ е интимна сцена на отворено, засенета со стари чинари. Во летните вечери тука се одржуваат солистички концерти, литературни читања и мали театарски форми.

Близината меѓу изведувачите и публиката, звуците на градот што стивнува и светлината на фасадата на катедралата создаваат атмосфера карактеристична само за Охрид.','Целосно рамен пристап од ул. Цар Самоил. Резервирани места за посетители со намалена подвижност во првиот ред.','Нумерирани столчиња во благ лак, поделени во два блока. Во случај на дожд програмата се преместува во црквата.'),
(3,'en','St. Sophia Atrium','An open-air stage in front of the cathedral for soloists, poetry and evenings under the stars.','The atrium of St. Sophia is an intimate open-air stage shaded by old plane trees. On summer evenings it hosts solo concerts, literary readings and small-scale theatre.

The closeness between performers and audience, the sounds of the town settling down and the light on the cathedral façade create an atmosphere found only in Ohrid.','Fully level access from Car Samoil St. Reserved spaces for visitors with reduced mobility in the first row.','Numbered chairs in a gentle arc, in two blocks. In case of rain the performance moves into the church.'),
(4,'mk','Долни Сарај','Тераса над езерото, отворена за џез, филм и современи програми.','Долни Сарај е плато над самиот брег на езерото, помеѓу „Св. Софија“ и Каневе. Со поглед кон водата и залезот, оваа сцена е омилено место за џез-концертите, филмските проекции на отворено и современите танцови изведби.

Терасите се поставени амфитеатрално, па и од последните редови има добар поглед кон сцената и езерото зад неа.','Пристап по калдрма од крајбрежната патека; за посетители со намалена подвижност е обезбеден превоз со електрично возило од пристаништето (по најава).','Нумерирани места на дрвени тераси. VIP-местата се на првата тераса, најблиску до сцената.'),
(4,'en','Dolni Saraj','A terrace above the lake, open to jazz, film and contemporary programmes.','Dolni Saraj is a plateau right above the lakeshore, between St. Sophia and Kaneo. Facing the water and the sunset, it is a favourite stage for jazz concerts, open-air film screenings and contemporary dance.

The terraces are laid out like an amphitheatre, so even the back rows have a good view of the stage and the lake behind it.','Access is along the cobbled lakeside path; for visitors with reduced mobility an electric shuttle runs from the harbour (on request).','Numbered seats on wooden terraces. VIP seats are on the first terrace, closest to the stage.'),
(5,'mk','ЦЗК „Григор Прличев“','Затворена сала со партер и балкон — дом на театарските гостувања и вонсезонските програми.','Центарот за култура „Григор Прличев“ го носи името на охридскиот поет и преродбеник. Неговата голема сала со партер и балкон е затворената сцена на фестивалот: тука се играат театарските гостувања, танцовите претстави и концертите од вонсезонската програма „Прелудиум“.

Салата е климатизирана, со професионално осветлување и надписи за претставите на странски јазици.','Лифт до балконот, рампа на главниот влез, прилагоден тоалет и индуктивна јамка за посетители со слушни апарати.','Партер со 16 реда и балкон со 4 реда. VIP-местата се во редовите 5–8 во средината на партерот, каде што звукот е најдобар.'),
(5,'en','Grigor Prlichev Cultural Centre','An indoor hall with stalls and balcony — home of visiting theatre and the off-season programme.','The Grigor Prlichev Cultural Centre bears the name of the Ohrid poet and figure of the national revival. Its large hall with stalls and balcony is the festival''s indoor stage: visiting theatre companies, dance performances and the off-season Prelude concerts take place here.

The hall is air-conditioned, with professional lighting and surtitles for performances in foreign languages.','Lift to the balcony, ramp at the main entrance, accessible toilet and an induction loop for visitors with hearing aids.','Stalls with 16 rows and a balcony with 4 rows. VIP seats are in rows 5–8 in the middle of the stalls, where the sound is best.'),
(6,'mk','Плаошник','Археолошкиот локалитет на Св. Климент — сцена на отворено без нумерирани места.','Плаошник е местото каде што Св. Климент Охридски ја основал првата словенска книжевна школа. Ливадата пред обновената црква „Св. Пантелејмон“ се претвора во сцена на отворено за поголеми концерти без нумерирани места — фестивални вечери за сите генерации.

Влезот е по стоечки/слободен распоред; донесете ќебе или перниче, а оние што сакаат да седат можат да дојдат порано.','Пристап по асфалтиран пат од Горна порта; одреден простор за посетители во инвалидски колички пред сцената.','Слободен распоред (без нумерирани места). Капацитетот е ограничен на 800 посетители.'),
(6,'en','Plaoshnik','The archaeological site of St. Clement — an open-air stage with general admission.','Plaoshnik is where St. Clement of Ohrid founded the first Slavic literary school. The meadow in front of the restored church of St. Panteleimon becomes an open-air stage for larger concerts without numbered seating — festival evenings for every generation.

Admission is general (standing/unreserved); bring a blanket or cushion, and come early if you would like to sit.','Paved access road from the Upper Gate; a dedicated area for wheelchair users in front of the stage.','General admission (no numbered seats). Capacity is limited to 800 visitors.');

Во последните сезони оркестарот посебно внимание посветува на македонските композитори, со праизведби на дела нарачани од фестивалот.'),
(1,'en','Ohrid Festival Orchestra','Symphony orchestra','The Ohrid Festival Orchestra is the resident ensemble that each summer brings together some seventy musicians from Macedonian orchestras and the diaspora. It performs the festival''s opening and closing ceremonies, the opera productions and the large symphonic works.

In recent seasons the orchestra has paid special attention to Macedonian composers, with premieres of works commissioned by the festival.'),
(2,'mk','Елена Марковска','Пијанистка','Елена Марковска студирала во Скопје и Виена, а денес настапува како солистка и камерна музичарка низ Европа. Нејзиниот репертоар се движи од Шуберт и Шопен до македонската клавирска литература, која ја снима за серијата „Охридски тетратки“.

На Охридско лето настапува редовно од 2019 година, а од 2025 води и мајсторски клас за млади пијанисти.'),
(2,'en','Elena Markovska','Pianist','Elena Markovska studied in Skopje and Vienna and today performs as a soloist and chamber musician across Europe. Her repertoire ranges from Schubert and Chopin to Macedonian piano literature, which she is recording for the series ''Ohrid Notebooks''.

She has appeared regularly at Ohrid Summer since 2019 and has led a masterclass for young pianists since 2025.'),
(3,'mk','Лука Ферарези','Диригент','Италијанскиот диригент Лука Ферарези е познат по своите интерпретации на Верди и Пучини и по работата со млади оркестри. Студирал во Милано, а подоцна бил асистент во неколку европски оперски куќи.

На Охридско лето го диригира свеченото отворање и оперската продукција на фестивалот, во соработка со Оркестарот на Охридско лето.'),
(3,'en','Luca Ferraresi','Conductor','Italian conductor Luca Ferraresi is known for his interpretations of Verdi and Puccini and for his work with youth orchestras. He studied in Milan and later served as an assistant at several European opera houses.

At Ohrid Summer he conducts the opening gala and the festival''s opera production with the Ohrid Festival Orchestra.'),
(4,'mk','Мари-Клер Дибоа','Сопран','Француската сопранистка Мари-Клер Дибоа ја гради кариерата на лирскиот репертоар — од Моцарт до Верди и Масне. Критиката го истакнува нејзиниот топол тон и драматската убедливост.

Во 2027 година ја пее Виолета во концертната поставка на „Травијата“ во Античкиот театар.'),
(4,'en','Marie-Claire Dubois','Soprano','French soprano Marie-Claire Dubois has built her career on the lyric repertoire — from Mozart to Verdi and Massenet. Critics praise her warm tone and dramatic conviction.

In 2027 she sings Violetta in the concert staging of La traviata at the Antique Theatre.'),
(5,'mk','Јонас Албрехт','Виолончелист','Германскиот виолончелист Јонас Албрехт е посветен на музиката на Бах и на современите композитори. Свири на инструмент од 1740 година, позајмен од фондација за млади уметници.

Неговиот интегрален циклус на Баховите свити за соло виолончело е снимен во црквите на неколку градови по патот на Via Egnatia.'),
(5,'en','Jonas Albrecht','Cellist','German cellist Jonas Albrecht is devoted to the music of Bach and to contemporary composers. He plays an instrument from 1740 on loan from a foundation for young artists.

His complete cycle of Bach''s suites for solo cello was recorded in churches of several towns along the Via Egnatia.'),
(6,'mk','Арта Краснићи','Виолинистка','Арта Краснићи е родена во Тирана и школувана во Лондон. Победничка е на неколку меѓународни натпревари, а нејзиниот прв албум со концертите на Сибелиус и Прокофјев беше добро примен од критиката.

Во Охрид настапува како солистка со Оркестарот на Охридско лето.'),
(6,'en','Arta Krasniqi','Violinist','Arta Krasniqi was born in Tirana and trained in London. She has won several international competitions, and her debut album of the Sibelius and Prokofiev concertos was warmly received by critics.

In Ohrid she appears as soloist with the Ohrid Festival Orchestra.'),
(7,'mk','Теодор Илиевски','Театарски режисер','Теодор Илиевски е режисер чии претстави ги поврзуваат античката драма и современиот сценски јазик. Неговите продукции гостувале на фестивали во Грција, Србија и Хрватска.

За Охридско лето ја режира „Медеја“ на Еврипид, создадена специјално за просторот на Античкиот театар.'),
(7,'en','Teodor Ilievski','Theatre director','Teodor Ilievski is a director whose productions connect ancient drama with a contemporary stage language. His work has toured festivals in Greece, Serbia and Croatia.

For Ohrid Summer he directs Euripides'' Medea, created specifically for the space of the Antique Theatre.'),
(8,'mk','Балкан брас колектив','Дувачки оркестар','Дванаесет музичари од Србија, Македонија и Бугарија кои балканските трубачки традиции ги спојуваат со џез и фанк. Нивните концерти се славни по енергијата — ретко кој останува да седи.

На Плаошник ќе ја изведат својата нова програма „Езерски марш“.'),
(8,'en','Balkan Brass Collective','Brass band','Twelve musicians from Serbia, North Macedonia and Bulgaria who fuse Balkan brass traditions with jazz and funk. Their concerts are famous for their energy — hardly anyone stays seated.

At Plaoshnik they present their new programme ''Lake March''.'),
(9,'mk','Балет Лихнидос','Балетска компанија','Балет Лихнидос е фестивална компанија формирана во 2023 година, која собира солисти од регионот и млади танчери од балетските училишта. Името го носи античкото име на Охрид.

Нивната нова продукција „Езеро од светлина“ е инспирирана од легендите за езерото.'),
(9,'en','Lychnidos Ballet','Ballet company','Lychnidos Ballet is a festival company formed in 2023 that brings together soloists from the region and young dancers from ballet schools. It takes its name from the ancient name of Ohrid.

Its new production ''Lake of Light'' is inspired by legends of the lake.'),
(10,'mk','Софија Андреу','Мецосопран','Грчката мецосопранистка Софија Андреу е подеднакво дома во ораториумот и во операта. Студирала во Солун и Минхен.

На Охридско лето настапува во Деветтата симфонија на Бетовен и во Реквиемот на Моцарт.'),
(10,'en','Sofia Andreou','Mezzo-soprano','Greek mezzo-soprano Sofia Andreou is equally at home in oratorio and opera. She studied in Thessaloniki and Munich.

At Ohrid Summer she appears in Beethoven''s Ninth Symphony and Mozart''s Requiem.'),
(11,'mk','Наѓа Ковалска','Кореографка','Полската кореографка Наѓа Ковалска создава современи танцови претстави за мали ансамбли, често во соработка со визуелни уметници. Нејзиниот јазик е прецизен и поетичен.

Претставата „Прагови“ е за пет танчери и жива електронска музика.'),
(11,'en','Nadia Kowalska','Choreographer','Polish choreographer Nadia Kowalska creates contemporary dance pieces for small ensembles, often in collaboration with visual artists. Her language is precise and poetic.

''Thresholds'' is a piece for five dancers and live electronics.'),
(12,'mk','Хана Сато','Виолинистка','Хана Сато е родена во Осака, а живее во Берлин. Позната е по камерната музика и по долгогодишното дуо со пијанистката Елена Марковска.

Нивната програма во Охрид ги обединува трите сонати за виолина и пијано од Брамс.'),
(12,'en','Hana Sato','Violinist','Hana Sato was born in Osaka and lives in Berlin. She is known for her chamber music and for her long-standing duo with pianist Elena Markovska.

Their Ohrid programme brings together Brahms''s three sonatas for violin and piano.'),
(13,'mk','Александар Трајков','Поет','Александар Трајков е поет и преведувач, автор на пет збирки поезија. Неговите стихови се преведени на неколку европски јазици.

На фестивалот ја води вечерта „Поезија крај езерото“ со гости од регионот.'),
(13,'en','Aleksandar Trajkov','Poet','Aleksandar Trajkov is a poet and translator, the author of five poetry collections. His work has been translated into several European languages.

At the festival he hosts the evening ''Poetry by the Lake'' with guests from the region.'),
(14,'mk','Куартето Лаго','Гудачки квартет','Квартетот е основан во Комо во 2016 година. Репертоарот им се движи од Хајдн до Шостакович и современите италијански композитори.

Во „Св. Софија“ ќе изведат програма што ги поврзува класичниот и модерниот квартет.'),
(14,'en','Quartetto Lago','String quartet','The quartet was founded in Como in 2016. Its repertoire ranges from Haydn to Shostakovich and contemporary Italian composers.

At St. Sophia they present a programme connecting the classical and the modern quartet.'),
(15,'mk','Мира Стојанова','Филмска режисерка','Мира Стојанова е документаристка чии филмови се занимаваат со водата, сеќавањето и малите заедници. Нејзиниот филм „Меморија на водата“ е снимен во текот на четири години покрај Охридското Езеро.

По проекцијата следува разговор со авторката.'),
(15,'en','Mira Stojanova','Film director','Mira Stojanova is a documentary filmmaker whose films deal with water, memory and small communities. Her film ''Water Memory'' was shot over four years along Lake Ohrid.

The screening is followed by a conversation with the director.'),
(16,'mk','Ансамбл Византион','Хор за рана музика','Машкиот вокален ансамбл Византион ја истражува византиската и старословенската црковна музика, работејќи со ракописи од охридските збирки.

Нивните концерти во „Св. Софија“ се враќаат на звукот за кој овој простор бил изграден.'),
(16,'en','Ensemble Byzantion','Early music choir','The male vocal ensemble Byzantion explores Byzantine and Old Church Slavonic sacred music, working from manuscripts in the Ohrid collections.

Their concerts at St. Sophia return to the sound for which the space was built.'),
(17,'mk','Даниел Окафор','Џез пијанист','Британскиот пијанист Даниел Окафор води трио што ги спојува џезот, госпелот и западноафриканските ритми. Неговите настапи се спонтани и полни со импровизација.

На Долни Сарај свири со тријото на заоѓање на сонцето.'),
(17,'en','Daniel Okafor','Jazz pianist','British pianist Daniel Okafor leads a trio that blends jazz, gospel and West African rhythms. His performances are spontaneous and full of improvisation.

At Dolni Saraj he plays with his trio at sunset.'),
(18,'mk','Компанија Театро делАква','Театарска компанија','Независна театарска компанија од Венеција што работи на границата меѓу драмата, движењето и музиката. Нивните претстави патуваат по медитеранските фестивали.

Во Охрид ја играат „Морето внатре“ — на италијански, со македонски и англиски надписи.'),
(18,'en','Compagnia Teatro dell''Acqua','Theatre company','An independent theatre company from Venice working at the border of drama, movement and music. Their productions tour Mediterranean festivals.

In Ohrid they perform ''The Sea Within'' — in Italian, with Macedonian and English surtitles.');

Во вториот дел Марковска ќе ги изведе „Охридските минијатури“, циклус на млад македонски композитор нарачан од фестивалот.','Ф. Шуберт — Соната во Б-дур, D 960
Ф. Шуберт — Четири импромптиа, D 899
„Охридски минијатури“ (праизведба)',NULL),
(1,'en','Prelude: Markovska Plays Schubert','Off-season ''Prelude'' series · piano recital','The autumn ''Prelude'' series brings the festival atmosphere back to Ohrid long before summer. The first evening belongs to pianist Elena Markovska and late Schubert — music full of serenity and quiet drama.

In the second half Markovska performs ''Ohrid Miniatures'', a cycle by a young Macedonian composer commissioned by the festival.','F. Schubert — Sonata in B-flat major, D 960
F. Schubert — Four Impromptus, D 899
''Ohrid Miniatures'' (world premiere)',NULL),
(2,'mk','Прелудиум: Песни на Охрид','Византиско и старословенско пеење','Ансамблот Византион во ноемвриската вечер ги изведува песнопенијата поврзани со охридските светители — Климент, Наум и Јован Зографски. Програмата е подготвена според ракописи од охридските збирки.

Концертот е во црквата „Св. Софија“, при природна акустика и пригушено осветлување.','Тропари и кондаци за Св. Климент Охридски
Стихири за Св. Наум
Канон од Охридскиот ракопис (реконструкција)',NULL),
(2,'en','Prelude: Songs of Ohrid','Byzantine and Old Church Slavonic chant','On a November evening Ensemble Byzantion performs hymns connected with the saints of Ohrid — Clement, Naum and John Zograf. The programme was prepared from manuscripts in the Ohrid collections.

The concert takes place in the Church of St. Sophia, with natural acoustics and dimmed lighting.','Troparia and kontakia for St. Clement of Ohrid
Stichera for St. Naum
Canon from the Ohrid manuscript (reconstruction)',NULL),
(3,'mk','Прелудиум: Фестивалот на филм','Архивски проекции и разговор','Вечер посветена на шест децении фестивалска историја на филмска лента: архивски снимки од првите концерти во „Св. Софија“, телевизиски записи од седумдесеттите и материјали од отворањето на Античкиот театар.

Вечерта ја води режисерката Мира Стојанова, која ги собира материјалите за идниот документарен филм за фестивалот.','Архивски снимки 1961–2001 (избор)
Разговор: „Како се снима музика на отворено“',NULL),
(3,'en','Prelude: The Festival on Film','Archival screenings and talk','An evening devoted to six decades of festival history on film: archive footage of the first concerts at St. Sophia, television recordings from the seventies and material from the opening of the Antique Theatre.

The evening is hosted by director Mira Stojanova, who is collecting material for a future documentary about the festival.','Archive footage 1961–2001 (selection)
Talk: ''How to film music in the open air''',NULL),
(4,'mk','Новогодишен концерт','Оркестар на Охридско лето · Виенски валцери и оперети','Традиционалниот новогодишен концерт на Оркестарот на Охридско лето ја затвора годината со валцери, полки и арии од оперети. Диригентот Лука Ферарези подготви програма полна со шарм и духовитост — од Јохан Штраус до Лехар.

После концертот публиката е поканета на чаша вино во фоајето.','Ј. Штраус II — „На убавиот син Дунав“
Ј. Штраус II — „Трич-трач полка“
Ф. Лехар — избор од „Веселата вдовица“
Ј. Штраус I — „Радецки марш“','Лука Ферарези'),
(4,'en','New Year''s Concert','Ohrid Festival Orchestra · Viennese waltzes and operetta','The traditional New Year''s concert of the Ohrid Festival Orchestra closes the year with waltzes, polkas and operetta arias. Conductor Luca Ferraresi has put together a programme full of charm and wit — from Johann Strauss to Lehár.

After the concert the audience is invited to a glass of wine in the foyer.','J. Strauss II — The Blue Danube
J. Strauss II — Tritsch-Tratsch-Polka
F. Lehár — selection from The Merry Widow
J. Strauss I — Radetzky March','Luca Ferraresi'),
(5,'mk','Свечено отворање: Деветтата на Бетовен','67. Охридско лето · Антички театар','Шеесет и седмото издание на Охридско лето се отвора со делото што ја слави човечката заедница — Деветтата симфонија на Бетовен. Под диригентската палка на Лука Ферарези, Оркестарот на Охридско лето и обединетите хорови ќе ја изведат „Одата на радоста“ на камените скалила на Античкиот театар.

Пред концертот, во 20:30, се одржува свечената церемонија на отворање со пригодно обраќање и фанфари над езерото.','Свечена церемонија на отворање
Л. ван Бетовен — Симфонија бр. 9 во д-мол, оп. 125','Лука Ферарези'),
(5,'en','Opening Gala: Beethoven''s Ninth','67th Ohrid Summer · Antique Theatre','The sixty-seventh Ohrid Summer opens with the work that celebrates human fellowship — Beethoven''s Ninth Symphony. Under Luca Ferraresi, the Ohrid Festival Orchestra and the combined choirs perform the ''Ode to Joy'' on the stone tiers of the Antique Theatre.

The official opening ceremony, with speeches and fanfares over the lake, begins at 20:30.','Official opening ceremony
L. van Beethoven — Symphony No. 9 in D minor, Op. 125','Luca Ferraresi'),
(6,'mk','Елена Марковска: Шопен и Скаловски','Клавирски рецитал во „Св. Софија“','Летниот рецитал на Елена Марковска поставува во дијалог две романтични имагинации — полската на Шопен и македонската на Тодор Скаловски. Ноктурната, баладите и танците се смалуваат во свод на „Св. Софија“ до шепот, а потоа повторно се распламтуваат.

Програмата е дел од серијата „Охридски тетратки“, во која пијанистката ја открива македонската клавирска литература.','Ф. Шопен — Балада бр. 1 во г-мол, оп. 23
Ф. Шопен — Ноктурна, оп. 48
Т. Скаловски — Македонски игри (избор)
Ф. Шопен — Полонеза-фантазија, оп. 61',NULL),
(6,'en','Elena Markovska: Chopin and Skalovski','Piano recital at St. Sophia','Elena Markovska''s summer recital places two Romantic imaginations in dialogue — Chopin''s Polish and Todor Skalovski''s Macedonian. Nocturnes, ballades and dances shrink to a whisper under the vaults of St. Sophia and then flare up again.

The programme belongs to the ''Ohrid Notebooks'' series, in which the pianist explores Macedonian piano literature.','F. Chopin — Ballade No. 1 in G minor, Op. 23
F. Chopin — Nocturnes, Op. 48
T. Skalovski — Macedonian Dances (selection)
F. Chopin — Polonaise-Fantaisie, Op. 61',NULL),
(7,'mk','Ноќно бдение: Византион','Рана музика · Византиско пеење','Доцна вечер, под фреските на „Св. Софија“, ансамблот Византион изведува програма составена како ноќно бдение — од вечерните химни до првите утрински стихири. Гласовите се движат низ просторот, а публиката е поканета да го доживее концертот без аплауз меѓу деловите.

Траење околу 75 минути, без пауза.','Вечерни химни од Охридскиот октоих
Молитвени пеења на Св. Наум
Утрински стихири (реконструкција)',NULL),
(7,'en','Night Vigil: Byzantion','Early music · Byzantine chant','Late in the evening, under the frescoes of St. Sophia, Ensemble Byzantion performs a programme shaped like a night vigil — from the evening hymns to the first morning stichera. The voices move through the space, and the audience is invited to experience the concert without applause between sections.

Duration about 75 minutes, without interval.','Evening hymns from the Ohrid Oktoechos
Prayer chants of St. Naum
Morning stichera (reconstruction)',NULL),
(8,'mk','Еврипид: Медеја','Премиера · Режија: Теодор Илиевски','Античката трагедија се враќа во античкиот театар. Теодор Илиевски ја поставува „Медеја“ како приказна за туѓинката што општеството ја користи и отфрла — со хор од дванаесет актерки и музика изведувана во живо.

Претставата е на македонски јазик, со англиски надписи. Не се препорачува за деца под 14 години.','Еврипид — „Медеја“ (превод на македонски)
Оригинална музика во живо
Изведба на македонски, англиски надписи','Теодор Илиевски'),
(8,'en','Euripides: Medea','Premiere · Directed by Teodor Ilievski','Ancient tragedy returns to the ancient theatre. Teodor Ilievski stages Medea as the story of a foreigner whom society uses and then casts aside — with a chorus of twelve actresses and live music.

Performed in Macedonian with English surtitles. Not recommended for children under 14.','Euripides — Medea (Macedonian translation)
Original live music
In Macedonian with English surtitles','Teodor Ilievski'),
(9,'mk','Јонас Албрехт: Свитите на Бах','Соло виолончело во предворјето','Шест свити, еден инструмент, една летна ноќ. Јонас Албрехт ги изведува трите свити од првата половина на циклусот (бр. 1, 3 и 5) во предворјето на „Св. Софија“ — музика што звучи интимно и монументално во исто време.

Во случај на дожд концертот се преместува во црквата.','Ј. С. Бах — Свита бр. 1 во Г-дур, BWV 1007
Ј. С. Бах — Свита бр. 3 во Ц-дур, BWV 1009
Ј. С. Бах — Свита бр. 5 во ц-мол, BWV 1011',NULL),
(9,'en','Jonas Albrecht: Bach Suites','Solo cello in the atrium','Six suites, one instrument, one summer night. Jonas Albrecht performs three suites (Nos. 1, 3 and 5) in the atrium of St. Sophia — music that sounds intimate and monumental at the same time.

In case of rain the concert moves into the church.','J. S. Bach — Suite No. 1 in G major, BWV 1007
J. S. Bach — Suite No. 3 in C major, BWV 1009
J. S. Bach — Suite No. 5 in C minor, BWV 1011',NULL),
(10,'mk','Верди: Травијата','Опера во концертна поставка','Најизведуваната опера на светот во најстариот театар во земјата. Мари-Клер Дибоа е Виолета Валери, а Лука Ферарези го води Оркестарот на Охридско лето во полусценска поставка со минимална сценографија и светлина што ја користи природата на просторот.

Опера во три чина, на италијански јазик со македонски и англиски надписи. Една пауза.','Ѓ. Верди — „Травијата“, опера во три чина
Изведба на италијански, надписи на македонски и англиски','Лука Ферарези'),
(10,'en','Verdi: La traviata','Opera in concert staging','The world''s most performed opera in the country''s oldest theatre. Marie-Claire Dubois is Violetta Valéry, and Luca Ferraresi leads the Ohrid Festival Orchestra in a semi-staged production with minimal scenery and lighting that uses the nature of the space.

Opera in three acts, sung in Italian with Macedonian and English surtitles. One interval.','G. Verdi — La traviata, opera in three acts
Sung in Italian, Macedonian and English surtitles','Luca Ferraresi'),
(11,'mk','Балкан брас колектив: Езерски марш','Концерт на отворено · слободен распоред','Трубите се враќаат на Плаошник! Балкан брас колектив ја претставува новата програма „Езерски марш“ — спој на македонски ора, српски трубачки традиции и њуорлеански фанк.

Влезот е без нумерирани места; капиите се отвораат во 20:30. Ќебињата се добредојдени.','„Езерски марш“ — нова програма
Традиционални ора во аранжмани на ансамблот',NULL),
(11,'en','Balkan Brass Collective: Lake March','Open-air concert · general admission','The trumpets are back at Plaoshnik! Balkan Brass Collective presents its new programme ''Lake March'' — a mix of Macedonian oro dances, Serbian brass traditions and New Orleans funk.

Admission without numbered seats; gates open at 20:30. Blankets welcome.','''Lake March'' — new programme
Traditional dances in the ensemble''s arrangements',NULL),
(12,'mk','Езеро од светлина','Балет Лихнидос · праизведба','Нова балетска продукција инспирирана од легендата за градот потонат под езерото. Кореографијата ги спојува класичниот балет и современиот танц, а музиката — оркестарска партитура на млад македонски композитор — ја изведува Оркестарот на Охридско лето.

Претставата е погодна за целото семејство.','„Езеро од светлина“ — балет во два дела (праизведба)
Музика: нарачка на Охридско лето',NULL),
(12,'en','Lake of Light','Lychnidos Ballet · world premiere','A new ballet production inspired by the legend of the town sunk beneath the lake. The choreography blends classical ballet and contemporary dance, and the music — an orchestral score by a young Macedonian composer — is performed by the Ohrid Festival Orchestra.

Suitable for the whole family.','''Lake of Light'' — ballet in two parts (world premiere)
Music: an Ohrid Summer commission',NULL),
(13,'mk','Поезија крај езерото','Литературна вечер со поети од регионот','Поети од Македонија, Албанија и Хрватска ги читаат своите стихови на мајчин јазик, а преводите се проектираат на фасадата на „Св. Софија“. Вечерта ја води поетот Александар Трајков.

По читањето следува разговор за преведувањето поезија и за јазиците што се среќаваат на брегот на езерото.','Читања на мајчин јазик со превод
Разговор: „Поезијата меѓу јазиците“',NULL),
(13,'en','Poetry by the Lake','A literary evening with poets from the region','Poets from North Macedonia, Albania and Croatia read their work in their mother tongues, while translations are projected onto the façade of St. Sophia. The evening is hosted by poet Aleksandar Trajkov.

The readings are followed by a conversation about translating poetry and about the languages that meet on the shores of the lake.','Readings in the original languages with translations
Talk: ''Poetry between languages''',NULL),
(14,'mk','Сато и Марковска: Брамс','Трите сонати за виолина и пијано','Дуото Хана Сато и Елена Марковска се враќа во Охрид со целосниот циклус на Брамсовите сонати за виолина и пијано — музика на зрелоста, топла и меланхолична. Овие сонати бараат партнери што слушаат еден со друг, а ова дуо свири заедно повеќе од десет години.','Ј. Брамс — Соната бр. 1 во Г-дур, оп. 78
Ј. Брамс — Соната бр. 2 во А-дур, оп. 100
Ј. Брамс — Соната бр. 3 во д-мол, оп. 108',NULL),
(14,'en','Sato & Markovska: Brahms','The three sonatas for violin and piano','The duo of Hana Sato and Elena Markovska returns to Ohrid with Brahms''s complete sonatas for violin and piano — music of maturity, warm and melancholic. These sonatas need partners who listen to each other, and this duo has played together for more than ten years.','J. Brahms — Sonata No. 1 in G major, Op. 78
J. Brahms — Sonata No. 2 in A major, Op. 100
J. Brahms — Sonata No. 3 in D minor, Op. 108',NULL),
(15,'mk','Меморија на водата','Проекција на отворено и разговор со авторката','Документарниот филм на Мира Стојанова ги следи рибарите, нуркачите-археолози и научниците што го проучуваат Охридското Езеро — едно од најстарите езера во Европа. Проекцијата е на платно на терасата на Долни Сарај, со езерото во позадина.

По проекцијата: разговор со режисерката и со дел од протагонистите.','„Меморија на водата“ (документарен, 82 мин.)
Разговор со авторката','Мира Стојанова'),
(15,'en','Water Memory','Open-air screening and talk with the director','Mira Stojanova''s documentary follows the fishermen, archaeological divers and scientists who study Lake Ohrid — one of the oldest lakes in Europe. The screening is on a big screen on the terrace of Dolni Saraj, with the lake in the background.

After the screening: a conversation with the director and some of the film''s protagonists.','Water Memory (documentary, 82 min.)
Talk with the director','Mira Stojanova'),
(16,'mk','Прагови','Современ танц · Кореографија: Наѓа Ковалска','Пет танчери ги истражуваат моментите кога се преминува од една состојба во друга — од сон во будење, од туѓина во дом. Музиката е електронска и се создава во живо, а светлото е дел од кореографијата.

Претставата е без зборови и е погодна за публика над 12 години.','„Прагови“ — танцова претстава за пет изведувачи и електроника во живо','Наѓа Ковалска'),
(16,'en','Thresholds','Contemporary dance · Choreography: Nadia Kowalska','Five dancers explore the moments of crossing from one state to another — from dream to waking, from foreign land to home. The electronic music is created live, and the lighting is part of the choreography.

The piece has no words and is suitable for audiences over 12.','''Thresholds'' — dance piece for five performers and live electronics','Nadia Kowalska'),
(17,'mk','Даниел Окафор трио: Џез на залез','Џез на терасата над езерото','Концертот почнува кога сонцето ќе допре до планините на албанскиот брег. Тријото на Даниел Окафор свири сопствени композиции и стандарди во кои госпелот и западноафриканските ритми се среќаваат со британскиот џез.

Барот на Долни Сарај работи за време на концертот.','Сопствени композиции и џез-стандарди',NULL),
(17,'en','Daniel Okafor Trio: Sunset Jazz','Jazz on the terrace above the lake','The concert begins as the sun touches the mountains on the Albanian shore. The Daniel Okafor Trio plays original compositions and standards in which gospel and West African rhythms meet British jazz.

The Dolni Saraj bar is open during the concert.','Original compositions and jazz standards',NULL),
(18,'mk','Куартето Лаго: Хајдн и Шостакович','Гудачки квартет во „Св. Софија“','Од ведрината на Хајдн до темната интензивност на Шостакович — Куартето Лаго гради програма што ги покажува двата пола на жанрот. Меѓу нив: краток квартет од современ италијански композитор, напишан за просторот на црквата.','Ј. Хајдн — Квартет оп. 76 бр. 4 „Изгрејсонце“
современ италијански композитор — „Lago“ (2026)
Д. Шостакович — Квартет бр. 8 во ц-мол, оп. 110',NULL),
(18,'en','Quartetto Lago: Haydn and Shostakovich','String quartet at St. Sophia','From Haydn''s serenity to Shostakovich''s dark intensity — Quartetto Lago builds a programme that shows both poles of the genre. In between: a short quartet by a contemporary Italian composer, written for the church''s acoustic.','J. Haydn — Quartet Op. 76 No. 4 ''Sunrise''
Contemporary Italian composer — ''Lago'' (2026)
D. Shostakovich — Quartet No. 8 in C minor, Op. 110',NULL),
(19,'mk','Морето внатре','Гостување · Компанија Театро делАква, Венеција','Тројца браќа и сестри се враќаат во родната куќа на венецијанската лагуна за да ја поделат оставината на мајка си. Помеѓу прагот и водата, сеќавањата се појавуваат како плима.

На италијански јазик, со македонски и англиски надписи.','„Морето внатре“ — претстава на Компанија Театро делАква
На италијански, надписи на македонски и англиски',NULL),
(19,'en','The Sea Within','Guest performance · Compagnia Teatro dell''Acqua, Venice','Three siblings return to their childhood home on the Venetian lagoon to divide their mother''s estate. Between the threshold and the water, memories rise like the tide.

In Italian with Macedonian and English surtitles.','''The Sea Within'' — Compagnia Teatro dell''Acqua
In Italian, Macedonian and English surtitles',NULL),
(20,'mk','Арта Краснићи: Сибелиус','Виолински концерт со Оркестарот на Охридско лето','Виолинистката Арта Краснићи го изведува Виолинскиот концерт на Сибелиус — едно од најтешките и најубавите дела за инструментот. Во вториот дел оркестарот ја свири Петтата симфонија на Чајковски.

Концертот е посветен на соработката меѓу двата брега на езерото.','Ж. Сибелиус — Концерт за виолина во д-мол, оп. 47
П. И. Чајковски — Симфонија бр. 5 во е-мол, оп. 64','Лука Ферарези'),
(20,'en','Arta Krasniqi: Sibelius','Violin concerto with the Ohrid Festival Orchestra','Violinist Arta Krasniqi performs Sibelius''s Violin Concerto — one of the most demanding and beautiful works for the instrument. In the second half the orchestra plays Tchaikovsky''s Fifth Symphony.

The concert is dedicated to cooperation between the two shores of the lake.','J. Sibelius — Violin Concerto in D minor, Op. 47
P. I. Tchaikovsky — Symphony No. 5 in E minor, Op. 64','Luca Ferraresi'),
(21,'mk','Свечено затворање: Реквиемот на Моцарт','Завршна вечер на 67. Охридско лето','Фестивалот се затвора со Реквиемот на Моцарт — дело што долго останува во тишината по последниот акорд. Солистите Мари-Клер Дибоа и Софија Андреу, обединетите хорови и Оркестарот на Охридско лето под водство на Лука Ферарези.

По концертот: доделување на фестивалските награди за 2027 година.','В. А. Моцарт — Реквием во д-мол, K. 626
Доделување на наградите на Охридско лето','Лука Ферарези'),
(21,'en','Closing Gala: Mozart''s Requiem','Final evening of the 67th Ohrid Summer','The festival closes with Mozart''s Requiem — a work that lingers long in the silence after the last chord. Soloists Marie-Claire Dubois and Sofia Andreou, the combined choirs and the Ohrid Festival Orchestra conducted by Luca Ferraresi.

After the concert: presentation of the Ohrid Summer awards for 2027.','W. A. Mozart — Requiem in D minor, K. 626
Presentation of the Ohrid Summer awards','Luca Ferraresi'),
(22,'mk','Мајсторски клас: отворена проба','Едукативна програма за млади пијанисти','Пијанистката Елена Марковска работи со четворица млади пијанисти пред публиката. Отворената проба е можност да се види како се гради интерпретација — од првиот такт до финалното темпо.

Слободен распоред на седење. Поволно за ученици и студенти по музика.','Работа со четворица учесници (репертоар по избор)',NULL),
(22,'en','Masterclass: Open Rehearsal','Educational programme for young pianists','Pianist Elena Markovska works with four young pianists in front of an audience. The open rehearsal is a chance to see how an interpretation is built — from the first bar to the final tempo.

Unreserved seating. Ideal for music pupils and students.','Work with four participants (repertoire of their choice)',NULL),
(23,'mk','Јубилејно отворање: 65 години','Карл Орф: Кармина бурана','Јубилејното 65. издание се отвори со „Кармина бурана“ и со видео-хроника на шест децении фестивал.','К. Орф — „Кармина бурана“','Лука Ферарези'),
(23,'en','Anniversary Opening: 65 Years','Carl Orff: Carmina Burana','The 65th anniversary edition opened with Carmina Burana and a video chronicle of six decades of the festival.','C. Orff — Carmina Burana','Luca Ferraresi'),
(24,'mk','Електра','Режија: Теодор Илиевски','Првата соработка на Илиевски со фестивалот — интензивна, физичка поставка на античката трагедија.','Софокле — „Електра“','Теодор Илиевски'),
(24,'en','Electra','Directed by Teodor Ilievski','Ilievski''s first collaboration with the festival — an intense, physical staging of the ancient tragedy.','Sophocles — Electra','Teodor Ilievski'),
(25,'mk','Куартето Лаго: Бетовен','Гудачки квартет','Доцните квартети на Бетовен во акустиката на „Св. Софија“.','Л. ван Бетовен — Квартет оп. 132',NULL),
(25,'en','Quartetto Lago: Beethoven','String quartet','Beethoven''s late quartets in the acoustics of St. Sophia.','L. van Beethoven — Quartet Op. 132',NULL),
(26,'mk','Нова сцена: Плаошник','Отворање на сцената на Плаошник','Првата фестивалска вечер на новата сцена на отворено на Плаошник.','Балкански дувачки програм',NULL),
(26,'en','New Stage: Plaoshnik','Opening of the Plaoshnik stage','The first festival evening on the new open-air stage at Plaoshnik.','Balkan brass programme',NULL),
(27,'mk','Поетски мостови','Литературна вечер','Поети од шест земји во вечер посветена на темата на изданието — „Мостови“.','Читања и разговор',NULL),
(27,'en','Poetic Bridges','Literary evening','Poets from six countries in an evening devoted to the edition''s theme, ''Bridges''.','Readings and talk',NULL),
(28,'mk','Оперска гала','Затворање на 65. издание','Гала-вечер со арии од Моцарт, Верди и Пучини — затворање на јубилејното издание.','Арии и дуети од Моцарт, Верди и Пучини','Лука Ферарези'),
(28,'en','Opera Gala','Closing of the 65th edition','A gala evening of arias by Mozart, Verdi and Puccini — closing the anniversary edition.','Arias and duets by Mozart, Verdi and Puccini','Luca Ferraresi'),
(29,'mk','Свечено отворање 2024','Верди: Реквием (избор)','64. издание се отвори со хорска програма посветена на гласот.','Ѓ. Верди — Реквием (избор)',NULL),
(29,'en','Opening Gala 2024','Verdi: Requiem (excerpts)','The 64th edition opened with a choral programme devoted to the voice.','G. Verdi — Requiem (excerpts)',NULL),
(30,'mk','Гласови на „Св. Софија“','Византиско пеење','Вечер на источната црковна музика во просторот на нејзиниот настанок.','Византиски химни',NULL),
(30,'en','Voices of St. Sophia','Byzantine chant','An evening of Eastern church music in the space where it was born.','Byzantine hymns',NULL),
(31,'mk','Марковска: Ноктурна','Клавирски рецитал','Ноќна програма од Шопен, Филд и Форе.','Ноктурна од Шопен, Филд и Форе',NULL),
(31,'en','Markovska: Nocturnes','Piano recital','A night programme of Chopin, Field and Fauré.','Nocturnes by Chopin, Field and Fauré',NULL),
(32,'mk','Тежина на водата','Современ танц','Првото гостување на Наѓа Ковалска во Охрид.','„Тежина на водата“','Наѓа Ковалска'),
(32,'en','Weight of Water','Contemporary dance','Nadia Kowalska''s first appearance in Ohrid.','''Weight of Water''','Nadia Kowalska'),
(33,'mk','Затворање 2024: Француска опера','Гуно и Бизе','Затворање со арии и сцени од „Фауст“ и „Кармен“.','Ш. Гуно — „Фауст“ (сцени)
Ж. Бизе — „Кармен“ (сцени)',NULL),
(33,'en','Closing 2024: French Opera','Gounod and Bizet','Closing night with arias and scenes from Faust and Carmen.','C. Gounod — Faust (scenes)
G. Bizet — Carmen (scenes)',NULL),
(34,'mk','Свечено отворање: „Љубов“','Оперски гала-концерт · Ермонела Јахо и Чарлс Кастроново','66. Охридско лето се отвори со оперскиот гала-концерт „Љубов“ во Античкиот театар, пред повеќе од 4.000 посетители. Сопранот Ермонела Јахо и американскиот тенор Чарлс Кастроново изведоа арии и дуети од големата оперска литература, со Оркестарот на Националната опера и балет под палката на италијанскиот маестро Марко Боеми.

Концертот беше распродаден две недели пред почетокот на фестивалот.','Арии и дуети од „Мадам Батерфлај“, „Тоска“, „Ромео и Јулија“, „Манон“ и „Адријана Лекуврер“
Дела од Понкиели, Чилеа, Џордано, Пучини, Сен-Санс, Гуно и Масне','Марко Боеми'),
(34,'en','Opening Gala: “Love”','Opera gala · Ermonela Jaho and Charles Castronovo','The 66th Ohrid Summer opened with the opera gala “Love” at the Antique Theatre, in front of more than 4,000 people. Soprano Ermonela Jaho and American tenor Charles Castronovo sang arias and duets from the great operatic repertoire with the Orchestra of the National Opera and Ballet, conducted by the Italian maestro Marco Boemi.

The concert sold out two weeks before the festival began.','Arias and duets from Madama Butterfly, Tosca, Roméo et Juliette, Manon and Adriana Lecouvreur
Works by Ponchielli, Cilea, Giordano, Puccini, Saint-Saëns, Gounod and Massenet','Marco Boemi'),
(35,'mk','„Татко“ — премиера','Флоријан Зелер · режија Иван Поповски','Премиерата на „Татко“ од Флоријан Зелер ја отвори драмската програма на 66. Охридско лето. Претставата ја режира Иван Поповски, а во главната улога настапи Бајруш Мјаку, кој со оваа вечер одбележа 53 години уметничка кариера.

Во улогите: Бајруш Мјаку, Амернис Нокшиќ, Фисник Зеќири, Сабина Мемиши Асланај, Мелика Кастрати и Флакрон Алији.','Флоријан Зелер — „Татко“',NULL),
(35,'en','The Father — premiere','Florian Zeller · directed by Ivan Popovski','The premiere of Florian Zeller''s The Father opened the drama programme of the 66th Ohrid Summer. The production was directed by Ivan Popovski, with Bajrush Mjaku in the title role, marking 53 years of his stage career.

Cast: Bajrush Mjaku, Amernis Nokshiq, Fisnik Zeqiri, Sabina Memishi Aslanaj, Melika Kastrati and Flakron Aliji.','Florian Zeller — The Father',NULL),
(36,'mk','Александер Мелников, пијано','Клавирски рецитал','Руско-германскиот пијанист Александер Мелников одржа целовечерен рецитал во црквата „Света Софија“ — една од првите класични вечери на 66. издание.','',NULL),
(36,'en','Alexander Melnikov, piano','Piano recital','Russian-German pianist Alexander Melnikov gave a full-evening recital at the Church of St. Sophia, one of the first classical evenings of the 66th edition.','',NULL),
(37,'mk','Симфониски оркестар „Нингбо“','Кина · диригент Абзал Мукитдин','Симфонискиот оркестар „Нингбо“ од Кина гостуваше на сцената „Долни Сарај“ под диригентската палка на Абзал Мукитдин од Казахстан. Програмата спои современи кинески дела, класицизам и традиционална кинеска музика.','Дела од Жу Житонг и Жанг Шуаи
В. А. Моцарт — Симфонија бр. 36 во До-дур „Линц“
Традиционална: „Месечина отсликана во втората пролет“','Абзал Мукитдин'),
(37,'en','Ningbo Symphony Orchestra','China · conductor Abzal Mukhitdin','The Ningbo Symphony Orchestra from China appeared on the Dolni Saraj stage under Kazakh conductor Abzal Mukhitdin. The programme combined contemporary Chinese works, Classical repertoire and traditional Chinese music.','Works by Zhu Zhitong and Zhang Shuai
W. A. Mozart — Symphony No. 36 in C major “Linz”
Traditional: “The Moon Reflected in the Second Spring”','Abzal Mukhitdin'),
(38,'mk','„Кориолан“ — премиера','Вилијам Шекспир · Народен театар Битола','Народниот театар од Битола премиерно ја изведе Шекспировата трагедија „Кориолан“ во режија на американскиот режисер Џон Блондел.

Во улогите: Васко Мавровски, Петар Горко, Борче Ѓаковски, Марјан Георгиевски, Сандра Грибовска, Јулијана Мирчевска и Петар Спировски.','Вилијам Шекспир — „Кориолан“',NULL),
(38,'en','Coriolanus — premiere','William Shakespeare · National Theatre Bitola','The National Theatre of Bitola premiered Shakespeare''s tragedy Coriolanus, directed by the American director John Blondell.

Cast: Vasko Mavrovski, Petar Gorko, Borche Gjakovski, Marjan Georgievski, Sandra Gribovska, Julijana Mirchevska and Petar Spirovski.','William Shakespeare — Coriolanus',NULL),
(39,'mk','Rising stars: Кимера трио','Клавирско трио од Италија','Италијанското клавирско трио „Кимера“ настапи во серијата „Rising stars“ посветена на младите уметници. Трио: Марта Черета (пијано), Стефано Ракањи (виолина) и Џорџо Лукини (виолончело).','',NULL),
(39,'en','Rising stars: Kimera Trio','Piano trio from Italy','The Italian piano trio Kimera appeared in the “Rising stars” series devoted to young artists. Marta Cerreta (piano), Stefano Rakanji (violin) and Giorgio Lukini (cello).','',NULL),
(40,'mk','„Митот за Амазонките“','АРТ Денс Театар · Грција','Грчкиот „АРТ Денс Театар“ го оживеа античкиот мит за Амазонките на сцената „Долни Сарај“. Режија и кореографија: Артемис Игнатиу, со музика компонирана посебно за претставата.','',NULL),
(40,'en','The Myth of the Amazons','ART Dance Theatre · Greece','Greece''s ART Dance Theatre brought the ancient myth of the Amazons to life on the Dolni Saraj stage. Direction and choreography by Artemis Ignatiou, with music composed especially for the production.','',NULL),
(41,'mk','Ана и Игор Дурловски и оркестарот „Ајга“','Македонската музичка традиција на Долни Сарај','Сопранистката Ана Дурловски и басот Игор Дурловски настапија со камерниот оркестар „Ајга“, под диригентската палка на Ана Спасовска, со концертмајстор Ева Богоевска. Вечерта беше посветена на македонската музичка традиција и привлече рекордна публика.','','Ана Спасовска'),
(41,'en','Ana and Igor Durlovski with the Ajga Orchestra','Macedonian musical tradition at Dolni Saraj','Soprano Ana Durlovski and bass Igor Durlovski performed with the chamber orchestra Ajga, conducted by Ana Spasovska with concertmaster Eva Bogoevska. The evening was devoted to the Macedonian musical tradition and drew a record audience.','','Ana Spasovska'),
(42,'mk','„Која е Лорет“','Театар за деца и младинци — Скопје','Претстава за прифаќањето, различностите и идентитетот, наменета пред сè за младата публика. Текст: Флоранс Кадије, режија: Драгана Милошевски-Попова.

Во улогите: Ана Левајковиќ Бошков, Мики Анчевски, Винета Дамческа Мојаноска, Петар Стојанов, Анастасија Ласовска и Вања Стојановиќ.','Флоранс Кадије — „Која е Лорет“',NULL),
(42,'en','Who Is Lorette?','Theatre for Children and Youth — Skopje','A play about acceptance, difference and identity, aimed above all at young audiences. Text by Florence Cadier, directed by Dragana Miloshevski-Popova.

Cast: Ana Levajkovikj Boshkov, Miki Anchevski, Vineta Damcheska Mojanoska, Petar Stojanov, Anastasija Lasovska and Vanja Stojanovikj.','Florence Cadier — Who Is Lorette?',NULL),
(43,'mk','Rising stars: Горјана Стојановска','Клавирски рецитал','Младата македонска пијанистка Горјана Стојановска настапи во серијата „Rising stars“ во црквата „Света Софија“.','',NULL),
(43,'en','Rising stars: Gorjana Stojanovska','Piano recital','The young Macedonian pianist Gorjana Stojanovska appeared in the “Rising stars” series at the Church of St. Sophia.','',NULL),
(44,'mk','„Алумни“ — 60 години ФМУ','Концерт по повод 60 години Факултет за музичка уметност — Скопје','Концерт со кој беа одбележани шест децении од Факултетот за музичка уметност при УКИМ во Скопје, со поранешни студенти кои денес се признати уметници.

Настапија: Катерина Костадиновска-Гелебешева, Глигор Гелебешев, Кристина Светиева, Милена Арсовска, Весна Гиновска Илкова, Златко Мадевски, Ана Дурловски, Игор Дурловски, Надица Ристиќ-Симовиќ, Дарко Багески и Јанинка Навчева.','Дела од Морлаки, Пуленк, Лист, Лалие, Белини, Верди, фон Супе, Хачатурјан и Пјацола',NULL),
(44,'en','“Alumni” — 60 years of the Faculty of Music','Concert for the 60th anniversary of the Faculty of Music Art, Skopje','A concert marking six decades of the Faculty of Music Art of Ss. Cyril and Methodius University in Skopje, performed by former students who are now established artists.

Performers: Katerina Kostadinovska-Gelebesheva, Gligor Gelebeshev, Kristina Svetieva, Milena Arsovska, Vesna Ginovska Ilkova, Zlatko Madevski, Ana Durlovski, Igor Durlovski, Nadica Ristikj-Simovikj, Darko Bageski and Janinka Navcheva.','Works by Morlacchi, Poulenc, Liszt, Lalliet, Bellini, Verdi, von Suppé, Khachaturian and Piazzolla',NULL),
(45,'mk','Словачка вечер','Гудачки квартет на Државниот камерен оркестар Жилина','Словачката вечер ја донесе гудачкиот квартет на Државниот камерен оркестар од Жилина: Роберт Копелман (прва виолина), Катерина Миронова (втора виолина), Александр Дјагилев (виола) и Дарја Земскаја (виолончело).','',NULL),
(45,'en','Slovak Evening','String quartet of the State Chamber Orchestra Žilina','The Slovak evening featured the string quartet of the State Chamber Orchestra Žilina: Robert Kopelman (first violin), Kateryna Mironova (second violin), Alexandr Djagilev (viola) and Daria Zemskaya (cello).','',NULL),
(46,'mk','„Кармен свита“ и „Болеро“','Балет · Опера и театар „Мадленијанум“, Србија','Опера и театар „Мадленијанум“ од Србија ги изведе двата балета во кореографија на Александар Илиќ — современа интерпретација на балетската класика на музика од Бизе и Равел.','„Кармен свита“ — по Ж. Бизе
М. Равел — „Болеро“',NULL),
(46,'en','Carmen Suite and Boléro','Ballet · Madlenianum Opera and Theatre, Serbia','The Madlenianum Opera and Theatre from Serbia performed both ballets in choreography by Aleksandar Ilić — a contemporary reading of ballet classics to music by Bizet and Ravel.','Carmen Suite — after G. Bizet
M. Ravel — Boléro',NULL),
(47,'mk','Камерен оркестар на НОБ','Диригент Бисера Чадловска · сопран Наде Талевска','Камерниот оркестар на Националната опера и балет, под палката на маестра Бисера Чадловска, со солистка сопранистката Наде Талевска. Програмата поврза италијанска и англиска музика со дела од македонски композитори.','Џ. Пучини — „Хризантеми“
Б. Бритн — Едноставна симфонија, оп. 4
Џ. Б. Перголези — Salve Regina во до-мол
Р. Аврамовски — Симфонија бр. 4 (I став)
Д. Шуплевски — Капричо бр. 1
Д. Имери — „Пајдушко“','Бисера Чадловска'),
(47,'en','NOB Chamber Orchestra','Conductor Bisera Chadlovska · soprano Nade Talevska','The Chamber Orchestra of the National Opera and Ballet under maestra Bisera Chadlovska, with soprano Nade Talevska as soloist. The programme paired Italian and English music with works by Macedonian composers.','G. Puccini — Crisantemi
B. Britten — Simple Symphony, Op. 4
G. B. Pergolesi — Salve Regina in C minor
R. Avramovski — Symphony No. 4 (1st movement)
D. Shuplevski — Capriccio No. 1
D. Imeri — Pajdushko','Bisera Chadlovska'),
(48,'mk','Австриска вечер','Денис Расел Дејвис и Маки Намекава · четирирачно пијано','Клавирското дуо Денис Расел Дејвис и Маки Намекава одржа концерт за четирирачно пијано што публиката долго ќе го памети. Во нивниот репертоар се и дела од Филип Глас и Стив Рајх.','',NULL),
(48,'en','Austrian Evening','Dennis Russell Davies and Maki Namekawa · piano four hands','The piano duo Dennis Russell Davies and Maki Namekawa gave a memorable concert for piano four hands. Their repertoire includes works by Philip Glass and Steve Reich.','',NULL),
(49,'mk','Шпанска вечер: трио „Вибрарт“','Клавирско трио','Триото „Вибрарт“, основано во Берлин: Хуан Перез Флористан (пијано), Мигел Колом Куеста (виолина) и Фернандо Ариас Фернандез (виолончело).','',NULL),
(49,'en','Spanish Evening: Vibrart Trio','Piano trio','The Berlin-founded Vibrart Trio: Juan Pérez Floristán (piano), Miguel Colom Cuesta (violin) and Fernando Arias Fernández (cello).','',NULL),
(50,'mk','Британска вечер: Исата Кане-Мејсон','Клавирски рецитал','Британската пијанистка Исата Кане-Мејсон ја воодушеви публиката на британската вечер, организирана со поддршка на Амбасадата на Обединетото Кралство. На вечерта беа доделени фестивалски плакети за поддршката и културната соработка.','',NULL),
(50,'en','British Evening: Isata Kanneh-Mason','Piano recital','British pianist Isata Kanneh-Mason delighted the audience at the British evening, held with the support of the British Embassy. Festival plaques for support and cultural cooperation were presented during the evening.','',NULL),
(51,'mk','Ансамбл „Алтус“','Камерна музика · диригент Ана Спасовска','Ансамблот „Алтус“ под раководство на Ана Спасовска изведе програма од македонски и француски автори.

Ансамбл: Гонца Богоромова-Краповски (сопран), Елена Стојческа (флејта), Игор Иванов (кларинет), Роман Петиот (гитара), Маријана Николовска (пијано), Мартин Димитров (виолина), Александар Лаовски (виола) и Паскал Краповски (виолончело).','Дела од Панде Шахов, Ангел Спировски, Томислав Зографски, Дарија Андовска, Дамјан Темков, Гијом Конесон, Морис Равел, Андре Капле и Камиј Сен-Санс','Ана Спасовска'),
(51,'en','Altus Ensemble','Chamber music · conductor Ana Spasovska','The Altus Ensemble, led by Ana Spasovska, performed a programme of Macedonian and French composers.

Ensemble: Gonca Bogoromova-Krapovski (soprano), Elena Stojcheska (flute), Igor Ivanov (clarinet), Roman Petiot (guitar), Marijana Nikolovska (piano), Martin Dimitrov (violin), Aleksandar Laovski (viola) and Paskal Krapovski (cello).','Works by Pande Shahov, Angel Spirovski, Tomislav Zografski, Darija Andovska, Damjan Temkov, Guillaume Connesson, Maurice Ravel, André Caplet and Camille Saint-Saëns','Ana Spasovska'),
(52,'mk','„Звук што расте“','40 години Камерен оркестар на МММ „Саша Николовски-Ѓумар“','Камерниот оркестар на Македонските музички младини „Саша Николовски-Ѓумар“ ги одбележа 40-те години постоење со концерт под диригентската палка на Иван Еминовиќ.','','Иван Еминовиќ'),
(52,'en','“A Growing Sound”','40 years of the Jeunesses Musicales Macedonia Chamber Orchestra','The chamber orchestra of Jeunesses Musicales Macedonia “Sasha Nikolovski-Gjumar” celebrated its 40th anniversary with a concert conducted by Ivan Eminovikj.','','Ivan Eminovikj'),
(53,'mk','Италијанска вечер: Кристијана Пегораро','Клавирски рецитал','Италијанската вечер, со поддршка на Амбасадата на Италија, ја донесе пијанистката Кристијана Пегораро.','',NULL),
(53,'en','Italian Evening: Cristiana Pegoraro','Piano recital','The Italian evening, supported by the Italian Embassy, featured pianist Cristiana Pegoraro.','',NULL),
(54,'mk','Француска вечер: квартет „Хермес“','Гудачки квартет','Традиционалната француска вечер, со поддршка на Амбасадата на Франција и Францускиот институт во Скопје, го донесе квартетот „Хермес“: Омер Буше и Елис Лиу (виолини), Лоу Јунг Хсин Чанг (виола) и Јан Левионоа (виолончело).','',NULL),
(54,'en','French Evening: Quatuor Hermès','String quartet','The traditional French evening, supported by the French Embassy and the Institut français in Skopje, featured Quatuor Hermès: Omer Bouchez and Élise Liu (violins), Yung-Hsin Lou Chang (viola) and Yan Levionnois (cello).','',NULL),
(55,'mk','Сигнум квартет','Саксофонски квартет · Словенија / Германија','Словенечко-германскиот саксофонски квартет „Сигнум“ спојува оригинална литература за саксофонски квартет, аранжмани на оркестарска и барокна музика и рок-класици. Состав: Михаил Кнот и Јакопо Тадеи (сопран саксофон), Алан Лужар (тенор саксофон) и Едоардо Зоти (баритон саксофон).','',NULL),
(55,'en','Signum Quartet','Saxophone quartet · Slovenia / Germany','The Slovenian-German saxophone quartet Signum combines original works for saxophone quartet, arrangements of orchestral and Baroque music, and rock classics. Line-up: Mihail Knot and Jacopo Taddei (soprano sax), Alan Lužar (tenor sax) and Edoardo Zotti (baritone sax).','',NULL),
(56,'mk','„Внатрешен глас на виолончелото и виолината“','Камерен оркестар од Битола · Емил Ровнер и Симон Поповски','Камерниот оркестар од Битола со австрискиот виолончелист Емил Ровнер и македонскиот виолинист Симон Поповски, под диригентската палка на Евгениј Шчербаков од Канада.','','Евгениј Шчербаков'),
(56,'en','“The Inner Voice of the Cello and the Violin”','Bitola Chamber Orchestra · Emil Rovner and Simon Popovski','The Bitola chamber orchestra with Austrian cellist Emil Rovner and Macedonian violinist Simon Popovski, conducted by Evgeny Shcherbakov from Canada.','','Evgeny Shcherbakov'),
(57,'mk','Вадим Холоденко, пијано','Клавирски рецитал','Украинскиот пијанист Вадим Холоденко ја изведе Фантазијата на Шуман и Фантастичната симфонија на Берлиоз во клавирска транскрипција на Лист.','Р. Шуман — Фантазија во До-дур, оп. 17
Х. Берлиоз / Ф. Лист — Фантастична симфонија',NULL),
(57,'en','Vadym Kholodenko, piano','Piano recital','Ukrainian pianist Vadym Kholodenko performed Schumann''s Fantasy and Berlioz''s Symphonie fantastique in Liszt''s piano transcription.','R. Schumann — Fantasie in C major, Op. 17
H. Berlioz / F. Liszt — Symphonie fantastique',NULL),
(58,'mk','Промоција: монографија „Ана Липша-Тофовиќ“','100 години од раѓањето на оперската примадона','На роденденот на фестивалот беше промовирана монографијата за Ана Липша-Тофовиќ, една од најголемите македонски оперски уметници, која на 4 август 1961 го одржа првиот солистички рецитал на Охридско лето. Автори: м-р Снежана Анастасова Чадиковска и проф. д-р Александар Трајковски. Монографијата ја промовира музикологот Марко Коловски.','',NULL),
(58,'en','Book launch: “Ana Lipsha-Tofovikj”','100 years since the birth of the opera prima donna','On the festival''s birthday, a monograph was launched about Ana Lipsha-Tofovikj, one of the greatest Macedonian opera artists, who gave the first solo recital of Ohrid Summer on 4 August 1961. Authors: Snezhana Anastasova Chadikovska and Prof. Aleksandar Trajkovski; presented by musicologist Marko Kolovski.','',NULL),
(59,'mk','Роденден на фестивалот: „Вокален и пијанистички огномет“','Мајан Лихт, контратенор · Пшемек Виницки, пијано','Фестивалот го прослави 66. роденден со концерт на израелскиот контратенор Мајан Лихт и полскиот пијанист Пшемек Виницки.','Арии од Хендл, Броски, Глинка, Шимановски, Персл и Бизе — „Ombra mai fu“, „Venti, turbini“, „Lascia ch''io pianga“, „The Cold Song“, Хабанера од „Кармен“
Дела од Менделсон и Бетовен, меѓу нив „Патетична соната“',NULL),
(59,'en','Festival birthday: “Vocal and Pianistic Fireworks”','Maayan Licht, countertenor · Przemek Winnicki, piano','The festival celebrated its 66th birthday with a concert by Israeli countertenor Maayan Licht and Polish pianist Przemek Winnicki.','Arias by Handel, Broschi, Glinka, Szymanowski, Persl and Bizet — “Ombra mai fu”, “Venti, turbini”, “Lascia ch''io pianga”, “The Cold Song”, the Habanera from Carmen
Works by Mendelssohn and Beethoven, including the “Pathétique” Sonata',NULL),
(60,'mk','Холандска вечер: Ниек Бар и Бен Ким','Сонатна вечер за виолина и пијано','Холандскиот виолинист Ниек Бар, кој свири на виолина „ex Fornbaum“ на Карло Бергонци од 1729 година, и американско-холандскиот пијанист Бен Ким.','С. Франк — Соната за виолина и пијано
