INSERT INTO `edition_translations` (`edition_id`,`lang`,`theme`,`summary`) VALUES
(1,'mk','Гласови на езерото','64. издание ги стави во фокус гласот и хорската традиција, со вечери посветени на византиското пеење и на оперската арија.'),
(1,'en','Voices of the Lake','The 64th edition focused on the voice and the choral tradition, with evenings devoted to Byzantine chant and the operatic aria.'),
(2,'mk','Мостови','Јубилејното 65. издание ги поврза Балканот и Европа преку копродукции, млади уметници и нова сцена на Плаошник.'),
(2,'en','Bridges','The 65th anniversary edition connected the Balkans and Europe through co-productions, young artists and a new stage at Plaoshnik.'),
(3,'mk','66. Охридско лето','40 дена, 48 настани и над 700 уметници од 24 земји — од оперската гала „Љубов“ во Античкиот театар до мјузиклот „Као какао“ на Долни Сарај.'),
(3,'en','66th Ohrid Summer','40 days, 48 events and more than 700 artists from 24 countries — from the opera gala “Love” at the Antique Theatre to the musical “Kao kakao” at Dolni Saraj.'),
(4,'mk','Хоризонти','67. издание ги отвора хоризонтите: 17 вечери на шест сцени, со солисти, ансамбли и продукции од десет земји.'),
(4,'en','Horizons','The 67th edition opens new horizons: seventeen evenings on six stages, with soloists, ensembles and productions from ten countries.');
