INSERT INTO `venue_translations` (`venue_id`,`lang`,`name`,`short_description`,`description`,`accessibility`,`seating_info`) VALUES
(1,'mk','Антички театар','Хеленистичкиот театар во срцето на Стариот град — главна сцена на фестивалот од 2001 година.','Античкиот театар во Охрид е изграден околу 200 година пред нашата ера и е единствениот театар од хеленистичкиот период во Македонија. Сместен меѓу Горната порта и Самоиловата тврдина, тој нуди поглед кон езерото што ја прави секоја вечер посебна.
