INSERT INTO `team_member_translations` (`member_id`,`lang`,`name`,`position`,`bio`) VALUES
(1,'mk','Ана Велковска','Директорка на фестивалот','Ја води фестивалската организација и меѓународната соработка. Претходно работела во културни институции во Скопје и Брисел.'),
(1,'en','Ana Velkovska','Festival Director','Leads the festival organisation and international cooperation. Previously worked at cultural institutions in Skopje and Brussels.'),
(2,'mk','Марко Ристевски','Уметнички директор — музика','Диригент и музиколог, одговорен за музичката и оперската програма.'),
(2,'en','Marko Ristevski','Artistic Director — Music','Conductor and musicologist responsible for the music and opera programme.'),
(3,'mk','Јана Петреска','Селекторка — театар и танц','Драматург со искуство на европски театарски фестивали.'),
(3,'en','Jana Petreska','Curator — Theatre and Dance','Dramaturg with experience at European theatre festivals.'),
(4,'mk','Димитар Николов','Раководител на продукција','Се грижи сцените на отворено секоја вечер да бидат подготвени — од звукот до столчињата.'),
(4,'en','Dimitar Nikolov','Head of Production','Makes sure the open-air stages are ready every evening — from sound to seating.'),
(5,'mk','Елена Тасева','Маркетинг и односи со јавноста','Комуникација, медиуми и дигитални канали на фестивалот.'),
(5,'en','Elena Taseva','Marketing & Public Relations','Communication, media and the festival''s digital channels.'),
(6,'mk','Бојан Ангелов','Билетарница и служба за посетители','Продажба на билети, групни резервации и пристапност.'),
(6,'en','Bojan Angelov','Box Office & Visitor Services','Ticket sales, group bookings and accessibility.'),
(7,'mk','Леа Хоџа','Меѓународна соработка','Копродукции, гостувања и членство во европските мрежи.'),
(7,'en','Lea Hoxha','International Relations','Co-productions, touring and membership of European networks.'),
(8,'mk','Иван Спасов','Координатор на волонтери','Ги регрутира, обучува и координира фестивалските волонтери.'),
(8,'en','Ivan Spasov','Volunteer Coordinator','Recruits, trains and coordinates the festival''s volunteers.');
